def assemble_order_items(cart_items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    order_items = []
    for item in cart_items:
        order_items.append({
            "product_id": item["product_id"],
            "name": item["name"],
            "quantity": item["quantity"],
            "unit_price": item["price"],
        })
    return order_items
